<script setup>
import {computed,ref,watchEffect} from 'vue'
import {useRoute,RouterLink} from 'vue-router'
import {projects} from '../data/projects.js'
import ProjectCard from '../components/ProjectCard.vue'
import {t,language,localized,labelCategory,labelStatus} from '../data/i18n.js'
const route=useRoute(),project=computed(()=>projects.find(p=>p.slug===route.params.slug))
const related=computed(()=>projects.filter(p=>p.slug!==project.value?.slug&&p.categories.some(c=>project.value?.categories.includes(c))).slice(0,3))
const feedback=ref('')
watchEffect(()=>{if(project.value)document.title=`${project.value.name} · Arvak Labs`})
async function share(){const url=window.location.href;try{if(navigator.share)await navigator.share({title:project.value.name,url});else if(navigator.clipboard){await navigator.clipboard.writeText(url);feedback.value=t('copied')}else feedback.value=t('copyManual')}catch(e){if(e.name!=='AbortError')feedback.value=t('copyManual')}}
const formatDate=(value)=>new Date(value+'T12:00:00').toLocaleDateString(language.value==='en'?'en-US':'pt-BR')
</script>
<template><div v-if="project" class="container detail-page"><RouterLink class="breadcrumb" to="/explorar">← {{t('back')}}</RouterLink><div class="detail-hero"><div><div class="overline">{{project.categories.map(labelCategory).join(' / ')}}</div><h1>{{project.name}}<span class="accent">.</span></h1><p class="detail-lead">{{localized(project,'short')}}</p><div class="detail-meta"><span class="status">{{labelStatus(project.status)}}</span><span v-if="project.version">{{t('version')}} {{project.version}}</span><span v-if="project.updated">{{t('updated')}} {{formatDate(project.updated)}}</span></div><div class="detail-actions"><a v-if="project.liveUrl" class="button primary" :href="project.liveUrl" target="_blank" rel="noopener noreferrer">{{t('launch')}} ↗</a><a v-if="project.repoUrl" class="button secondary" :href="project.repoUrl" target="_blank" rel="noopener noreferrer">{{t('source')}} ↗</a><a v-if="project.docsUrl" class="button secondary" :href="project.docsUrl" target="_blank" rel="noopener noreferrer">{{t('docs')}} ↗</a><button class="button quiet" type="button" @click="share">{{t('share')}} ↗</button></div><p v-if="feedback" class="feedback" role="status">{{feedback}}</p></div><div class="detail-visual" :class="`cover-${project.id}`"><img v-if="project.cover" :src="project.cover" :alt="project.name"/><span v-else aria-hidden="true">{{project.monogram}}</span></div></div><div v-if="project.screenshots?.length" class="screenshots"><img v-for="image in project.screenshots" :key="image" :src="image" :alt="project.name" loading="lazy"></div><div class="detail-columns"><article class="detail-prose"><div class="overline">{{t('inside')}}</div><h2>{{t('idea')}}</h2><p>{{localized(project,'description')}}</p><template v-if="project.problem"><h2>{{t('problem')}}</h2><p>{{localized(project,'problem')}}</p></template><template v-if="project.features?.length"><h2>{{t('features')}}</h2><ul class="feature-list"><li v-for="(f,i) in project.features" :key="i">{{typeof f==='string'?f:(f[language]||f.en)}}</li></ul></template><template v-if="project.challenges?.length"><h2>{{t('challenges')}}</h2><ul class="feature-list"><li v-for="(f,i) in project.challenges" :key="i">{{typeof f==='string'?f:(f[language]||f.en)}}</li></ul></template><template v-if="project.learnings?.length"><h2>{{t('learnings')}}</h2><ul class="feature-list"><li v-for="(f,i) in project.learnings" :key="i">{{typeof f==='string'?f:(f[language]||f.en)}}</li></ul></template></article><aside class="detail-sidebar"><div class="side-card"><span class="overline">{{t('stack')}}</span><h3>{{t('technologies')}}</h3><div class="tags large"><span v-for="tech in project.technologies" :key="tech">{{tech}}</span></div><hr><h3>{{t('category')}}</h3><div class="tags large"><span v-for="c in project.categories" :key="c">{{labelCategory(c)}}</span></div></div></aside></div><section v-if="related.length" class="section related"><div class="section-heading"><div><span class="overline">{{t('related')}}</span><h2>{{t('relatedHeading')}}<span class="accent">.</span></h2></div></div><div class="project-grid"><ProjectCard v-for="p in related" :key="p.id" :project="p"/></div></section></div><div v-else class="container empty-state"><h1>{{t('notFound')}}</h1><p>{{t('notFoundDesc')}}</p><RouterLink class="button primary" to="/explorar">{{t('exploreProjects')}}</RouterLink></div></template>
